  for(int ao:new int[]{0,2})for(boolean forge:new boolean[]{false,true})for(int light:new int[]{0,15,240,0x00F000F0}){
   mc.gameSettings.ambientOcclusion=ao;net.minecraftforge.client.MinecraftForgeClient.getRenderPass();net.minecraftforge.common.ForgeModContainer.forgeLightPipelineEnabled=forge;jar.lightlevel=light;BufferBuilder actual=buffer(),expected=buffer();boolean a=NativeSceneBlockDraw.append(jar,jar.getBlockState(pos),pos,actual),e=dispatch.renderBlock(jar.getBlockState(pos),pos,jar,expected);check(a&&a==e,"real scene route returns native renderer result");Draw normal=new Draw(actual),direct=new Draw(expected);check(Arrays.equals(normal.data,direct.data),"scene bytes exactly native dispatcher with lighting retained");check(normal.count==20,"shared native solid face culled against finite jar neighbour");BufferBuilder colorless=NativeSceneBlockDraw.finishColorless(actual);check(!colorless.getVertexFormat().hasColor()&&colorless.getVertexFormat().getSize()==24&&colorless.getVertexCount()==normal.count,"preview omits COLOR, not zero-filled fake BLOCK channels");ByteBuffer src=normal.bytes(),dst=colorless.getByteBuffer();for(int v=0;v<normal.count;v++){for(int j=0;j<12;j++)check(src.get(v*28+j)==dst.get(v*24+j),"position byte preserved");for(int j=0;j<12;j++)check(src.get(v*28+16+j)==dst.get(v*24+12+j),"native UV/light bytes preserved after lighting");}expected.finishDrawing();
  }
