  jar.setBlock(0,0,0,Blocks.WOOL,14);check(jar.getBlockState(BlockPos.ORIGIN).getBlock().getMetaFromState(jar.getBlockState(BlockPos.ORIGIN))==14,"jar native metadata retained");check(jar.getCombinedLight(pos,0)==jar.lightlevel,"raw original jar light integer not silently normalized");
  for(int metadata=0;metadata<16;metadata++){jar.setBlock(0,0,0,Blocks.WOOL,metadata);IBlockState state=NativeSceneBlockDraw.sliceState(Blocks.LOG,jar,BlockPos.ORIGIN);check(state.equals(Blocks.LOG.getStateFromMeta(metadata)),"slice source block gets DESTINATION native metadata "+metadata);}
